import java.nio.file.Path;
import java.util.List;
import org.apache.maven.model.building.DefaultModelBuilderFactory;
import org.apache.maven.model.building.DefaultModelBuildingRequest;
import org.codehaus.plexus.util.xml.Xpp3Dom;
public final class CheckDocweaveSigning {
 public static void main(String[] args) throws Exception {
  var root=Path.of(args[0]); var builder=new DefaultModelBuilderFactory().newInstance();
  var raw=builder.build(new DefaultModelBuildingRequest().setPomFile(root.resolve("pom.xml").toFile()).setSystemProperties(System.getProperties())).getEffectiveModel();
  var paths=new java.util.ArrayList<String>(); paths.add(""); paths.addAll(raw.getModules());
  int checks=0;
  for(var profiles:List.of(List.<String>of(),List.of("release-artifacts"),List.of("release-artifacts","release-signing"))) {
   for(var path:paths) {
    var model=builder.build(new DefaultModelBuildingRequest().setPomFile(root.resolve(path).resolve("pom.xml").toFile()).setSystemProperties(System.getProperties()).setActiveProfileIds(profiles)).getEffectiveModel();
    var sign=model.getBuild().getPlugins().stream().filter(p->p.getArtifactId().equals("maven-gpg-plugin")).findFirst();
    if(!profiles.contains("release-signing")) { if(sign.isPresent()) throw new AssertionError("Signing active by default"); }
    else {
     var p=sign.orElseThrow();var c=(Xpp3Dom)p.getConfiguration();
     boolean internal=path.equals("docweave-validation")||path.equals("docweave-integration-tests");
     if(!p.getVersion().equals("3.2.8") || !c.getChild("bestPractices").getValue().equals("true") || !c.getChild("skip").getValue().equals(Boolean.toString(internal))) throw new AssertionError(path+" "+c);
     var e=p.getExecutions().getFirst(); if(!e.getPhase().equals("verify")||!e.getGoals().equals(List.of("sign")))throw new AssertionError(path);
    }
    checks++;
   }
  }
  System.out.println("PASS: "+checks+" effective models; default/attachment builds unsigned, 17 publishable POMs sign, 2 internal harnesses skip");
 }
}
